# Code generated by Claude
"""Diagnostic for F2/F3: at one or more floor spots, the finder's own requirement verdicts per pedestal height beside the region's, to see which criterion differs.

    MUJOCO_GL=egl python experiments/bench_stance_diag.py [x y]...
"""
import sys
import numpy as np

from experiments.bench_stance_validate import scene_objects
import mujoco
from src import bench_stance as bs
from src.furniture_map import FurnitureMap
from src.stance_finder import region_scores
from src.task_points import task_points
from src.stance_checks import StanceChecks
from src.stance_finder import robot_geometry
from src.task_beaker_hotplate import load_task
from src.task_config import BENCH_STANCE_CFG, TASK_CFG

if __name__ == "__main__":
    sim = load_task()
    m, d = sim.model, sim.data
    rg = robot_geometry(m)
    chk = StanceChecks(m, d, rg["base_z"])
    qs = bs.pedestal_commands()
    yaw = TASK_CFG["staging_yaw"]
    cams = bs.camera_poses(m, qs, chk=chk, ref_stance=(*TASK_CFG["staging_xy"], yaw), cache_dir=BENCH_STANCE_CFG["cache_dir"])
    maps = bs.load_maps("data/reach_map", sides=("left",))
    objs = scene_objects(m, d)
    regs = {o["name"]: bs.get_region(maps, rg, cams, o["depth"], bs.spec_in_base_frame(o, yaw, rg["base_z"])) for o in objs}
    n, t = bs.bench_frame(yaw)
    furn = FurnitureMap.from_model(m, mujoco.MjData(m), exclude_bodies=("task_beaker",))
    allmaps = bs.load_maps("data/reach_map", sides=("left",))
    fpts = [dict(p, arm="left") for p in task_points(m, d)]
    FX, FY, FS = region_scores(fpts, allmaps, furn, rg, yaw, qs)
    fs = FS["left"]
    args = [float(v) for v in sys.argv[1:]]
    spots = [tuple(args[i:i + 2]) for i in range(0, len(args), 2)] or [tuple(TASK_CFG["staging_xy"])]
    for (x, y) in spots:
        print(f"== spot ({x:.3f}, {y:.3f})")
        iyf, ixf = int(np.argmin(abs(FY[:, 0] - y))), int(np.argmin(abs(FX[0] - x)))
        print(" finder quick search (12 task points, any bin, furniture) tolerance cm per q:", [round(100 * float(fs[i, iyf, ixf]), 1) for i in range(len(qs))])
        print(" q    | finder: home mm  placed mm  view%  hidden beaker/hotplate  fails       | region: reach bins (beaker, hotplate)  view ok (b,h)  ")
        for qi, q in enumerate(qs):
            r = chk.requirements((x, y, yaw, q))
            occ = r["occlusion"]
            row = []
            for o in objs:
                reg = regs[o["name"]]
                dxy = np.asarray(o["xy"]) - np.array([x, y])
                b, oo = float(dxy @ n), float(dxy @ t)
                ib, io = int(round((b - reg["b"][0]) / 0.01)), int(round((oo - reg["o"][0]) / 0.01))
                row.append((int(reg["reach"][qi, :, ib, io].sum()), bool(reg["view"][qi, ib, io])))
            print(f" {q:.2f} | {1000 * r['home_clearance']['arms']:7.0f} {r['placed_beaker_mm'] if r['placed_beaker_mm'] is None else round(r['placed_beaker_mm']):>8}  {'-' if r['view'] is None else round(100 * r['view']['margin']):>5}  "
                  f"{'-' if occ is None else '%.2f/%.2f' % (occ['beaker_hidden_frac'], occ['hotplate_hidden_frac']):>10}   {','.join(r['failed']) or 'ok':12s} | beaker {row[0][0]} {row[0][1]}  hotplate {row[1][0]} {row[1][1]}")
